use vstd::prelude::*;

verus! {

/// Spec-level definition of right-rotation of a sequence by `r` positions.
/// (Assumes `0 <= r < len` and `len > 0`.)
spec fn rotate_right_seq<T>(s: Seq<T>, r: nat) -> Seq<T>
    decreases s.len()
{
    let len = s.len();
    // For the cases we use it, len > 0 and r < len.
    // Split at s = len - r: result is tail ++ head.
    s.subrange(len - r, len) + s.subrange(0, len - r)
}

fn rotate_right(list: &Vec<u32>, n: usize) -> (out: Vec<u32>)
    requires
        list.len() > 0,
    ensures
        out@ == rotate_right_seq(list@, (n % list.len()) as nat),
        out.len() == list.len(),
{
    let len = list.len();
    assert!(len > 0, "input list must be non-empty");

    let r = n % len; // effective right rotation

    if r == 0 {
        // If r == 0, rotate_right_seq(list@, 0) == list@.
        assert(rotate_right_seq(list@, 0) == list@) by {
            let l = list@.len();
            assert(l > 0);
            assert(list@.subrange(l - 0, l) == Seq::<u32>::empty());
            assert(list@.subrange(0, l - 0) == list@);
        }
        return list.clone();
    }

    let s = len - r; // split point
    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[s..]);
    new_list.extend_from_slice(&list[..s]);

    // Establish the abstract content of `new_list`.
    assert(out@ == rotate_right_seq(list@, r as nat)) by {
        let l = list@.len();
        assert(l == len as nat);
        assert(0 < r);
        assert(r < len); // since r = n % len and len > 0

        // After first extend:
        // new_list@ == list@[s..len]
        // After second extend:
        // new_list@ == list@[s..len] + list@[0..s]
        //
        // This matches rotate_right_seq with split point len - r == s.
        assert((len - r) as nat == l - (r as nat));
    };

    new_list
}

} // verus!

